import { Node, Tween, tween, UITransform } from 'cc';

/** Full slot width of each progress viewport, taken before it is first resized. */
const slots = new WeakMap<Node, number>();
/** Running width animation per viewport. */
const animations = new WeakMap<Node, { width: number; target: number }>();

/**
 * Shows ratio 0..1 on a progress bar generated by tools/v2/build-ui.mjs (progressSlots): the
 * element is a left-anchored rect-mask viewport over the full-width fill picture, so only its
 * width changes and the left end never moves. 0 hides the fill; there is no minimum width.
 * seconds > 0 animates from the shown width.
 */
export function setProgress(node: Node, ratio: number, seconds = 0): void {
    const ui = node.getComponent(UITransform)!;
    if (!slots.has(node)) slots.set(node, ui.width);
    const p = Number.isFinite(ratio) ? Math.min(1, Math.max(0, ratio)) : 0;
    if (!Number.isFinite(ratio)) console.error(`progress ${node.name}: invalid ratio ${ratio}`);
    const target = slots.get(node)! * p, apply = (width: number) => { ui.width = width; node.active = width > 0.5; };
    const running = animations.get(node);
    // A repaint with the value already being animated to lets the animation finish.
    if (running && Math.abs(running.target - target) < 0.01) return;
    if (running) { Tween.stopAllByTarget(running); animations.delete(node); }
    if (seconds <= 0) { apply(target); return; }
    const state = { width: node.active ? ui.width : 0, target };
    animations.set(node, state);
    tween(state).to(seconds, { width: target }, { easing: 'quadOut', onUpdate: () => apply(state.width) })
        .call(() => { animations.delete(node); apply(target); }).start();
}
